insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El remate$vn$), $vn$FINES-003$vn$, $vn$Introduce The Team$vn$, $vn$Después, te voy a presentar al equipo de Bolton. Solo tomará unos minutos. Ellos estarán contigo durante los próximos XX meses en cada paso del camino, asegurándose de tu éxito y comprometidos a mejorar tu futuro financiero. Son los expertos mejor capacitados de la industria y prácticamente todos mis clientes ven su puntaje por encima de 700 al completar el programa y han resuelto su deuda.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Después, te voy a presentar al equipo de Bolton. Solo tomará unos minutos. Ellos estarán contigo durante los próximos XX meses en cada paso del camino, asegurándose de tu éxito y comprometidos a mejorar tu futuro financiero. Son los expertos mejor capacitados de la industria y prácticamente todos mis clientes ven su puntaje por encima de 700 al completar el programa y han resuelto su deuda."}]$vn$::jsonb, null, null, null, 30, $vn$Hand them off with confidence. How you talk about the team is how they will feel about the team.$vn$, $vn$I am being passed to people who know what they are doing.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El remate$vn$), $vn$FINES-004$vn$, $vn$The Handoff$vn$, $vn$¿Hola (nombre del cliente)?... ¡Excelente! Tenemos a (Nombre del AM.) en la línea para tu llamada de bienvenida. Él/Ella lleva mucho tiempo haciendo esto, y siempre cuida muy bien a mis clientes. Sé que hará lo mismo contigo. Me voy a quedar en la línea, pero (Nombre del AM.) va a encargarse de aquí en adelante, ¿ok?... ¡Excelente! (Nombre del AM.) ¡adelante!$vn$, array[]::text[], $vn$[{"tone": "", "text": "¿Hola (nombre del cliente)?... ¡Excelente! Tenemos a (Nombre del AM.) en la línea para tu llamada de bienvenida. Él/Ella lleva mucho tiempo haciendo esto, y siempre cuida muy bien a mis clientes. Sé que hará lo mismo contigo. Me voy a quedar en la línea, pero (Nombre del AM.) va a encargarse de aquí en adelante, ¿ok?... ¡Excelente! (Nombre del AM.) ¡adelante!"}]$vn$::jsonb, null, $vn$Cuando regreses a la línea con el AM$vn$, null, 40, $vn$Warm and quick. Saying you are staying on the line is what keeps them from feeling dropped.$vn$, $vn$I am not being handed off and abandoned.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El remate$vn$), $vn$FINES-005$vn$, $vn$Weather The Storm$vn$, $vn$Muy bien XXX, ¡felicidades por terminar tu inscripción! Ya está todo listo y de aquí en adelante vas a estar en buenas manos con Bolton Services Group. Antes de que te vayas, déjame dejarte unas palabras de sabiduría. XXX, acabas de inscribirte en un programa que va a tomar algo de tiempo. Como la mayoría de las cosas que toman tiempo, puede que sientas ansiedad o te frustres con el progreso. Cuando y si eso pasa, por favor, por favor, por favor recuerda estas palabras: Aguanta la tormenta, confía en el proceso. Vas a quedar libre de deudas y tu crédito se va a recuperar a través de este programa. Estás con el mejor equipo del país y este es el mejor programa disponible, por eso trabajamos con ellos. Punto. ¡Tú puedes!” (Despídete)$vn$, array[]::text[], $vn$[{"tone": "", "text": "Muy bien XXX, ¡felicidades por terminar tu inscripción! Ya está todo listo y de aquí en adelante vas a estar en buenas manos con Bolton Services Group. Antes de que te vayas, déjame dejarte unas palabras de sabiduría. XXX, acabas de inscribirte en un programa que va a tomar algo de tiempo. Como la mayoría de las cosas que toman tiempo, puede que sientas ansiedad o te frustres con el progreso. Cuando y si eso pasa, por favor, por favor, por favor recuerda estas palabras: Aguanta la tormenta, confía en el proceso. Vas a quedar libre de deudas y tu crédito se va a recuperar a través de este programa. Estás con el mejor equipo del país y este es el mejor programa disponible, por eso trabajamos con ellos. Punto. ¡Tú puedes!” (Despídete)"}]$vn$::jsonb, null, $vn$Tan pronto como el AM termine y te invite de regreso a la línea. (Despídete)$vn$, null, 50, $vn$Start calm and personal, then finish with certainty. "Weather the storm, trust the process" should be said slowly enough that they could repeat it back.$vn$, $vn$Someone believes I can do this.$vn$, false, 'published');
